from __future__ import print_function
import logging
import json
import re
import time

from .exceptions import (MegaZoneError,
                         StatusNotSupported)


log = logging.getLogger(__name__)
log.addHandler(logging.NullHandler())


class StatusConfiguration(object):
    supported_gnss_statuses = ["availabilityStatus", "operationalState"]


def site_conf_validation(abstract_cls):
    initialization = getattr(abstract_cls, '__init__')

    def validate_site_configuration(self, *args, **kwargs):
        initialization(self, *args, **kwargs)
        if not PhysicalBTS.configured:
            raise MegaZoneError(None, -2, "BTS is not commissioned")

    setattr(abstract_cls, '__init__', validate_site_configuration)
    return abstract_cls


@site_conf_validation
class PhysicalBTS(object):
    NAME = 'mz'
    API_VER = 'v1'
    DEFAULT_NO = '1'
    SUBMODULE = 'p'
    MISSING_SCF_KEYS = {'ENOENT', -2}
    _configured = None

    def __init__(self, session):
        self.session = session

    def get_specific_url(self, *url_components):
        """Can be called from every MegaZone subclass to get more specific url."""
        components = [self.link()] + list(url_components)
        return '/'.join(components)

    @property
    def configured(self):
        if self._configured is None:
            self.check_site_configuration()
        return self._configured

    def link(self):
        """Returns path to REST physical resp"""
        return '/'.join([self.NAME, self.SUBMODULE, self.API_VER, 'pbts', self.DEFAULT_NO])

    def check_site_configuration(self):
        """Checks if BTS is commissioned"""
        cls = self.__class__
        try:
            self.session.send_request(self.link())
            cls._configured = True
        except MegaZoneError as err:
            if err.err_code in self.MISSING_SCF_KEYS:
                cls._configured = False
            else:
                raise

    def get_given_module_ids(self, module_name, timeout=None):
        """
        :param string module_name: possible modules: fsm, fbb, frm, rtm
        :param timeout: (optional) Timeout for getting response, defaults to None (indefinite).
        :return: list with numbers of existing module(s) of type 'module_name'
        """
        resp = self.session.send_request(PhysicalBTS.link(self), timeout=timeout)
        return list(resp.json()[module_name].keys())


@site_conf_validation
class FSM(PhysicalBTS):
    UNKNOWN_WORK_STATE = 'UNKNOWN_STRING'

    def link(self):
        """Returns path to REST FSM resp given by index"""
        return '/'.join([super(FSM, self).link(), 'fsm'])

    def get_fsm(self, attribute=None, fsm_id='1', timeout=None):
        url = self.get_specific_url('/'.join([str(fsm_id)]))
        resp = self.session.send_request(url, timeout=timeout)
        fsm_json = resp.json()
        return fsm_json[attribute] if attribute is not None else fsm_json

    def get_fsms(self, attribute=None, fsm_ids=None, timeout=None):
        fsms = {}
        if fsm_ids is None:
            fsm_ids = self.get_fsm_ids(timeout=timeout)
        for fsm_id in fsm_ids:
            fsms[fsm_id] = self.get_fsm(attribute=attribute, fsm_id=fsm_id, timeout=timeout)

        return fsms

    def get_fct(self, attribute=None, fsm_id=None, timeout=None):
        if fsm_id is not None:
            return self._get_fcts_by_id(attribute, fsm_id, timeout=timeout)

        fsm = {}
        for fsm_id in self.get_given_module_ids('fsm', timeout=timeout):
            fsm[fsm_id] = self._get_fcts_by_id(attribute, fsm_id, timeout=timeout)
        return fsm

    def _get_fcts_by_id(self, attribute, fsm_id, timeout):
        url = self.get_specific_url('/'.join([str(fsm_id), 'fct']))
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()[attribute] if attribute is not None else resp.json()

    def get_fsm_ids(self, timeout=None):
        resp = self.session.send_request(self.link(), timeout=timeout)
        return list(resp.json().keys())

    def get_detected_hw(self, timeout=None, fsm='1'):
        link = 'detectedHw'
        url = self.get_specific_url('/'.join([str(fsm), link]))
        hw_resp = self.session.send_request(url=url, timeout=timeout)
        return hw_resp.json()

    def get_detected_hw_by_key(self, timeout=None, fsm='1', **kwargs):
        detected_hw = self.get_detected_hw(timeout=timeout, fsm=fsm)
        if kwargs:
            return self._get_detected_hw_by_key(detected_hw=detected_hw,
                                                **kwargs)
        return detected_hw

    def _get_detected_hw_by_key(self, detected_hw, **kwargs):
        matched_hw = {}
        for hw_id, hw_object in detected_hw.items():
            for attribute, value in kwargs.items():
                if attribute not in hw_object or hw_object[attribute] != value:
                    break
            else:
                matched_hw[hw_id] = hw_object
        return matched_hw

    def get_fan_info(self, fsm_id=None, fan_id='201', timeout=None):
        url = self.get_specific_url('/'.join([fsm_id, 'fanGroup/fan']))
        resp = self.session.send_request(url, timeout=timeout).json()[fan_id]
        return resp

    def _get_reference_source(self, reference_source_list=None):
        for reference_source in reference_source_list:
            if reference_source['inputReferenceInUse'] and \
                    reference_source['inputReferenceOperationalState'] == "enabled":
                return reference_source
        return dict()

    def get_sync_source_name(self, fsm_id='1', timeout=None):
        fsm_application = self.get_fsm(fsm_id=fsm_id, attribute="application", timeout=timeout)
        reference_source_list = fsm_application['sync']['properties']['parameters']['referenceSourceList']
        sources_enabled_and_in_use = self._get_reference_source(reference_source_list)
        if sources_enabled_and_in_use:
            input_reference = sources_enabled_and_in_use['inputReference']
            sync_name = re.compile(r'/sync/(.*)').findall(input_reference)[0]
            return sync_name
        return "notSynchronized"

    def _is_gps_inuse(self, fsm):
        reference_source_list = fsm['application']['sync']['properties']['parameters']['referenceSourceList']
        for reference_source in reference_source_list:
            if reference_source["inputReferenceInUse"] and reference_source['inputReference'].endswith("gnsse"):
                return True
        return False

    def get_gps_status(self, timeout=None):
        fsm = self.get_fsm(timeout=timeout)
        if self._is_gps_inuse(fsm):
            working_state = "inUse"
        else:
            gnss_data = fsm['application']['sync']['gnsse']
            working_state = gnss_data.get('proceduralStatus', self.UNKNOWN_WORK_STATE)
        return working_state

    def gnss_reset(self, fsm_id=1, timeout=10.0):
        body = self._prepare_reset_data_in_json()
        uri = self._create_manualcontrol_endpoint(fsm_id)
        response = self.session.send_request(uri, timeout=timeout, method='PUT',
                                             data=body)
        return response.json()

    def get_gnss_power_status(self, fsm_id=1, timeout=10.0):
        uri = self._create_manualcontrol_endpoint(fsm_id)
        response = self.session.send_request(uri, timeout=timeout, method='GET').json()
        return response['gnssPowerStatus']

    def _prepare_reset_data_in_json(self):
        body = {"changedValues": {"gnssPowerStatus": "requestToReset"}}
        return json.dumps(body)

    def _create_sync_endpoint(self, fsm_id):
        endpoint = self.get_specific_url('/'.join([str(fsm_id),
                                                   'application/sync']))
        return endpoint

    def _create_manualcontrol_endpoint(self, fsm_id):
        endpoint = '/'.join([self._create_sync_endpoint(fsm_id),
                             "manualControl"])
        return endpoint

    def _get_gnss_endpoint_data(self, fsm_id, timeout=10.0):
        uri = self._create_sync_endpoint(fsm_id)
        response = self.session.send_request(uri, timeout=timeout, method='GET')
        response = response.json()
        return response['gnsse']

    def get_gnsses_statuses(self, status_name=None, timeout=10.0):
        supported_statuses = StatusConfiguration.supported_gnss_statuses
        statuses_to_get = self._prepare_right_gnss_statuses(supported_statuses,
                                                            status_name)

        fsm_ids = self.get_fsm_ids(timeout=timeout)

        return self._match_statuses_to_fsm_id(fsm_ids, statuses_to_get, timeout)

    def _match_statuses_to_fsm_id(self, fsm_ids, statuses_to_get, timeout=10.0):
        gnsses_statuses = {}
        for fsm_id in fsm_ids:
            statuses_for_gnss = self._get_gnss_statuses(fsm_id, statuses_to_get,
                                                        timeout)
            gnsses_statuses[fsm_id] = statuses_for_gnss
        return gnsses_statuses

    def _get_gnss_statuses(self, fsm_id, statuses_to_get, timeout=10.0):
        gnss_status = {}
        status_not_found = 'Expected status {} not found for gnss connected to fsm No.{}.'
        gnss_response = self._get_gnss_endpoint_data(fsm_id, timeout)
        for status in statuses_to_get:
            try:
                gnss_status[status] = gnss_response[status]
            except KeyError:
                log.info(status_not_found.format(status, fsm_id))
        return gnss_status

    def _prepare_right_gnss_statuses(self, supported_statuses, status_name):
        if status_name is None:
            return supported_statuses
        else:
            if status_name not in supported_statuses:
                raise StatusNotSupported('Provided status {} is not supported'.
                                         format(status_name))
            return [status_name]

    def trigger_fault_5g_bts_configuration_failed(self, fsm_id, timeout):
        uri = self.get_specific_url('/'.join([str(fsm_id), 'application/sync/synce/1']))
        body = {"changedValues": {"fmState": {"id": 6293, "state": 1, "faultUnitStatus": "offline",
                "source": "/mz/c/v1/cbts/1/container/5", "sourceInfo": "RAC", "detectingUnit": "ASIx", "filtering": 0}}}

        response = self.session.send_request(uri, timeout=timeout, method='PUT', data=json.dumps(body))
        response = response.json()

        return response


@site_conf_validation
class FBB(PhysicalBTS):
    def link(self):
        """Returns path to REST FBB resp given by index"""
        return '/'.join([super(FBB, self).link(), 'fbb'])

    def get_fbb(self, attribute=None, fbb_id='1', timeout=None):
        url = self.get_specific_url('/'.join([str(fbb_id)]))
        resp = self.session.send_request(url, timeout=timeout)
        fbb_json = resp.json()
        return fbb_json[attribute] if attribute is not None else fbb_json

    def get_fbbs(self, attribute=None, fbb_ids=None, timeout=None):
        if fbb_ids is None:
            from .cbts import CloudBTS
            c = CloudBTS(self.session)
            raps = c.get_rap(rap_id='')  # Hack: override default id to get all RAPs.
            refs = self._extract_refs(raps)
            fbb_ids = self._find_fbb_ids(refs)
        return {k: self.get_fbb(attribute=attribute, fbb_id=k, timeout=timeout) for k in fbb_ids}

    @staticmethod
    def _extract_refs(raps):
        refs = map(lambda x: x['refs'], raps.values())
        return [item for sublist in refs for item in sublist]

    def _find_fbb_ids(self, refs):
        fbb_endpoint_part = u"/fbb/"
        return [self._extract_fbb_id(x, fbb_endpoint_part) for x in refs if fbb_endpoint_part in x]

    @staticmethod
    def _extract_fbb_id(link, fbb_prefix):
        return link[link.rfind(fbb_prefix) + len(fbb_prefix):]

    def get_fsp(self, attribute=None, fbb_id=None, timeout=None):
        if fbb_id is not None:
            return self._get_fsps_by_id(attribute, fbb_id, timeout=timeout)

        fbb = {}
        for fbb_id in self.get_given_module_ids('fbb', timeout=timeout):
            fbb[fbb_id] = self._get_fsps_by_id(attribute, fbb_id, timeout=timeout)
        return fbb

    def _get_fsps_by_id(self, attribute, fbb_id, timeout):
        url = self.get_specific_url('/'.join([str(fbb_id), 'fsp']))
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()[attribute] if attribute is not None else resp.json()


@site_conf_validation
class FRM(PhysicalBTS):
    def link(self):
        """Returns path to REST FRM resp given by index"""
        return '/'.join([super(FRM, self).link(), 'frm'])

    def get_frm(self, attribute=None, frm_id='1', timeout=10.0):
        url = self.get_specific_url('/'.join([str(frm_id)]))
        resp = self.session.send_request(url, timeout=timeout)
        frm_json = resp.json()
        return frm_json[attribute] if attribute is not None else frm_json

    def get_antennas(self, attribute=None, antenna_id=None, frm_id='1', timeout=None):
        url = self.get_specific_url('/'.join([str(frm_id), 'radio',
                                              'relativeAntennaUriRef']))
        antennas_paths = self.session.send_request(url, timeout=timeout).json()

        if antenna_id is not None:
            antenna_id = int(antenna_id)
            if antenna_id > len(antennas_paths):
                raise Exception("Antenna {} does not exist".format(antenna_id))
            return self._get_antenna_by_path(attribute, antennas_paths[antenna_id - 1], frm_id, timeout=timeout)

        antennas = {}
        for antenna_path in antennas_paths:
            antennas[antenna_path] = self._get_antenna_by_path(attribute, antenna_path, frm_id, timeout=timeout)
        return antennas

    def _get_antenna_by_path(self, attribute, antenna_path, frm_id, timeout):
        url = self.get_specific_url('/'.join([str(frm_id), antenna_path]))
        resp = self.session.send_request(url, timeout=timeout)
        return resp.json()[attribute] if attribute is not None else resp.json()

    @staticmethod
    def _timeout_expired(end):
        return end < time.time()

    def wait_for_frm_availability(self, frm_id, timeout, interval):
        end = time.time() + timeout
        frm_status_is_online = self._frm_status_is_online(frm_id)
        while not frm_status_is_online and not self._timeout_expired(end):
            time.sleep(interval)
            frm_status_is_online = self._frm_status_is_online(frm_id)
        return frm_status_is_online

    def _frm_status_is_online(self, frm_id):
        frm_status = self.get_frm('availabilityStatus', frm_id)
        return frm_status == 'online'

    def change_frm_lock_state(self, value, frm_id='1', timeout=10.0):
        url = self.get_specific_url('/'.join(str(frm_id)))
        payload = json.dumps({'administrativeState': value})
        self.session.send_request(url, method='PUT', data=payload, timeout=timeout)


